<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Generate Certificate</h1><p>Create and manage persisted student or employee certificates.</p></div></header><section class="module-card"><div class="module-card__body"><form method="post" action="<?= url('/admin/certificates') ?>"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Template</label><select class="module-select" name="template_id" required><option value="achievement">Achievement</option><option value="participation">Participation</option><option value="service">Service</option></select></div><div class="module-field"><label>Recipient Type</label><select class="module-select" name="recipient_type" required><option value="student">Student</option><option value="employee">Staff</option></select></div><div class="module-field"><label>Student</label><select class="module-select" name="student_id"><option value="">None</option><?php foreach($students as$s):?><option value="<?= $s['id'] ?>"><?= e($s['student_name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Staff</label><select class="module-select" name="staff_id"><option value="">None</option><?php foreach($employees as$e):?><option value="<?= $e['id'] ?>"><?= e($e['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label>Achievement</label><input class="module-input" name="achievement"></div><div class="module-field"><label>Date</label><input class="module-input" type="date" name="date" value="<?= date('Y-m-d') ?>" required></div></div><button class="btn btn--primary">Generate Certificate</button></form></div></section><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>ID</th><th>Template</th><th>Type</th><th>Recipient</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($certificates as$c):?><tr><td><?= $c['id'] ?></td><td><?= e($c['template']) ?></td><td><?= e($c['recipient_type']) ?></td><td><?= e($c['recipient_name']) ?></td><td><?= e($c['certificate_date']) ?></td><td><form method="post" action="<?= url('/admin/certificates/'.$c['id'].'/delete') ?>"><?= csrf_field() ?><button class="btn btn--danger" onclick="return confirm('Delete certificate?')">Delete</button></form></td></tr><?php endforeach ?></tbody></table></div></section></div></div></main>
